import operator
from functools import reduce

print(reduce(operator.mul, [1, 2, 3, 4]))          # 24
print(reduce(operator.or_, [{1, 2}, {2, 3}, {4}])) # {1, 2, 3, 4}
print(reduce(operator.add, [], 0))                 # 0
try:
    reduce(operator.add, [])
except TypeError as e:
    print("empty without initial")                 # empty without initial

def compose(*funcs):
    return reduce(lambda f, g: lambda x: g(f(x)), funcs)
pipeline = compose(str.strip, str.lower, str.title)
print(pipeline("  hELLO wORLD "))                   # Hello World

config = {"db": {"primary": {"host": "10.0.0.5"}}}
print(reduce(operator.getitem, ["db", "primary", "host"], config))  # 10.0.0.5

from functools import cache, lru_cache

calls = 0
@cache
def fib(n):
    global calls
    calls += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(80), calls)            # 23416728348467685 81
print(fib.cache_info())
# CacheInfo(hits=78, misses=81, maxsize=None, currsize=81)

@lru_cache(maxsize=2)
def lookup(code):
    print("computing", code)
    return code.upper()
lookup("a"); lookup("b"); lookup("a"); lookup("c"); lookup("b")
# computing a / computing b / computing c / computing b
try:
    fib([1])
except TypeError as e:
    print(e)                     # unhashable type: 'list'

from functools import cmp_to_key

def bigger_concat(a, b):
    return (a + b < b + a) - (a + b > b + a)   # -1, 0 or 1

nums = ["3", "30", "34", "5", "9"]
print("".join(sorted(nums, key=cmp_to_key(bigger_concat))))  # 9534330

users = [("ann", 31), ("bob", 25), ("cy", 31)]
print(sorted(users, key=lambda u: (-u[1], u[0])))
# [('ann', 31), ('cy', 31), ('bob', 25)]

def by_length_then_alpha(a, b):
    if len(a) != len(b):
        return len(a) - len(b)
    return (a > b) - (a < b)
print(sorted(["pear", "fig", "apple", "kiwi"], key=cmp_to_key(by_length_then_alpha)))
# ['fig', 'kiwi', 'pear', 'apple']

concepts.body:
A decorator replaces a function with a **wrapper function** that does something extra and then calls the original. Without help, the wrapper's metadata is its own: `__name__` becomes `"wrapper"`, the docstring disappears, and `inspect.signature` shows `(*args, **kwargs)`. That breaks `help()`, error messages, log lines that print function names, and tools such as pytest that read a function's parameters.

`@functools.wraps(func)` on the inner function copies the metadata over:

```python
def logged(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        ...
        return func(*args, **kwargs)
    return wrapper
```

It copies `__module__`, `__name__`, `__qualname__`, `__doc__`, `__annotations__` and `__type_params__`, merges the wrapper's `__dict__` with the original's, and sets **`__wrapped__`** to point at the original function. `inspect.signature` follows `__wrapped__`, so the real signature shows up, and in tests you can reach the undecorated function as `f.__wrapped__`.

Decorators that take their own arguments, like `@timed("db")`, need one more level: an outer function takes the arguments and returns the actual decorator.

Make it a habit: every decorator you write that wraps a function should use `@wraps`.

