import inspect
import time
from functools import wraps

def timed(label):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            try:
                return func(*args, **kwargs)
            finally:
                print(f"[{label}] {func.__name__} took {time.perf_counter() - start:.0f}s")
        return wrapper
    return decorator

@timed("db")
def fetch(user_id: int, *, fresh: bool = False) -> dict:
    """Load a user record."""
    return {"id": user_id}

print(fetch(7))                 # [db] fetch took 0s  then {'id': 7}
print(fetch.__name__, fetch.__doc__)   # fetch Load a user record.
print(inspect.signature(fetch))        # (user_id: int, *, fresh: bool = False) -> dict
print(fetch.__wrapped__(8))            # {'id': 8}  (undecorated)

from functools import cached_property

class Dataset:
    def __init__(self, values):
        self.values = values
        self.computations = 0

    @cached_property
    def mean(self):
        self.computations += 1
        return sum(self.values) / len(self.values)

d = Dataset([2, 4, 6])
print(d.mean, d.mean, d.computations)   # 4.0 4.0 1
print("mean" in vars(d))                 # True: stored on the instance

d.values.append(8)
print(d.mean)                            # 4.0  (stale!)
del d.mean                               # invalidate
print(d.mean, d.computations)            # 5.0 2

from functools import total_ordering

@total_ordering
class Version:
    def __init__(self, text):
        self.parts = tuple(int(p) for p in text.split("."))
    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.parts == other.parts
    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.parts < other.parts
    def __hash__(self):
        return hash(self.parts)
    def __repr__(self):
        return "v" + ".".join(map(str, self.parts))

vs = [Version("1.10.0"), Version("1.2.3"), Version("1.2")]
print(sorted(vs))                              # [v1.2, v1.2.3, v1.10.0]
print(Version("2.0") >= Version("1.9"))        # True  (generated)
print(max(vs), Version("1.2") in {Version("1.2")})   # v1.10.0 True

concepts.body:
Often one function must do something different for each type: format a date one way, a number another. `@singledispatch` lets you write a separate version for each type and register it; on each call, Python **dispatches**, picking the version that matches the type of the **first** argument.

```python
@singledispatch
def to_json(obj):
    raise TypeError(f"can't serialise {type(obj).__name__}")
@to_json.register
def _(obj: datetime):
    return obj.isoformat()
```

The undecorated first function is the fallback for any type without its own version.

Registration options:

- Annotate the first parameter and use `@f.register` (shown above). Since 3.11, `int | float` (either type) registers several types at once.
- Pass the type explicitly: `@f.register(Decimal)`, or `f.register(Path, str)` for an existing function.

Dispatch follows the **MRO**: a version registered for a base class also handles its subclasses, unless a more specific one exists. `bool` goes to the `int` version if there's no `bool` one. Abstract base classes work too: registering for `collections.abc.Mapping` covers dicts and other dict-like types.

The big advantage over `if isinstance(...)` chains is that other modules can register versions for their own types without editing your function.

`f.registry` maps types to versions, and `f.dispatch(cls)` shows which one would be used. For methods, use `singledispatchmethod`, which looks at the first argument after `self`.

