from collections.abc import Mapping
from datetime import date
from decimal import Decimal
from functools import singledispatch

@singledispatch
def render(obj):
    return repr(obj)                       # fallback for unknown types
@render.register
def _(obj: int | float):                   # union registration, 3.11+
    return f"{obj:,}"

@render.register
def _(obj: date):
    return obj.strftime("%d %b %Y")

@render.register(Mapping)
def _(obj):
    return ", ".join(f"{k}={render(v)}" for k, v in obj.items())

print(render(1234567))                     # 1,234,567
print(render({"due": date(2025, 3, 1), "total": 1500.5}))
# due=01 Mar 2025, total=1,500.5
print(render(True), render(Decimal("2")))  # 1 Decimal('2')  (bool -> int impl)
print(render.dispatch(bool).__name__)      # _

import warnings
from functools import partial, partialmethod, singledispatchmethod

class Light:
    on = False
    def set_state(self, on): self.on = on
    turn_on = partialmethod(set_state, True)
light = Light(); light.turn_on(); print(light.on)   # True
class Formatter:
    @singledispatchmethod
    def format(self, value):
        return str(value)
    @format.register
    def _(self, value: float):
        return f"{value:.2f}"
    @format.register
    def _(self, value: list):
        return "[" + "; ".join(self.format(v) for v in value) + "]"
print(Formatter().format([1, 2.5, "x"]))   # [1; 2.50; x]
class Bad:
    hello = partial(print, "hi")      # not bound to instances
with warnings.catch_warnings(record=True) as caught:
    warnings.simplefilter("always")
    Bad().hello                       # attribute access warns in 3.13
print(caught[0].category.__name__)    # FutureWarning

import inspect
from functools import wraps

def with_retries(func):
    @wraps(func)
    def wrapper(*args, retries=3, **kwargs):
        for attempt in range(retries):
            try:
                return func(*args, **kwargs)
            except ConnectionError:
                if attempt == retries - 1:
                    raise
    sig = inspect.signature(func)
    extra = inspect.Parameter("retries", inspect.Parameter.KEYWORD_ONLY, default=3)
    wrapper.__signature__ = sig.replace(parameters=[*sig.parameters.values(), extra])
    return wrapper

@with_retries
def fetch(url: str) -> str:
    return f"GET {url}"

print(inspect.signature(fetch))          # (url: str, *, retries=3) -> str
print(inspect.unwrap(fetch) is fetch.__wrapped__)   # True
print(fetch("x", retries=1))             # GET x

from collections.abc import Iterable, Sized
from functools import singledispatch

@singledispatch
def describe(obj): return "object"
@describe.register
def _(obj: Sized): return "sized"
@describe.register
def _(obj: Iterable): return "iterable"
class Box:                    # counts as Sized only (has __len__)
    def __len__(self): return 1
class Bag:                    # counts as both Sized and Iterable
    def __len__(self): return 0
    def __iter__(self): return iter(())
print(describe(Box()))        # sized
try:
    describe(Bag())
except RuntimeError as e:
    print(str(e)[:18])        # Ambiguous dispatch
describe.register(Bag, lambda obj: "bag")
print(describe(Bag()))        # bag
try:
    describe.register(list[int], lambda obj: "ints")
except TypeError:
    print("list[int] rejected")   # list[int] rejected
